import math
from statistics import NormalDist

N = NormalDist()


def d1(S, K, T, sig, r=0.0):
    return (math.log(S / K) + (r + 0.5 * sig**2) * T) / (sig * math.sqrt(T))


def bs(kind, S, K, T, sig, r=0.0):
    x = d1(S, K, T, sig, r)
    y = x - sig * math.sqrt(T)
    if kind == "call":
        return S * N.cdf(x) - K * math.exp(-r * T) * N.cdf(y)
    return K * math.exp(-r * T) * N.cdf(-y) - S * N.cdf(-x)


def strike_for_delta(kind, target, S, T, sig, r=0.0):
    z = N.inv_cdf(target)
    x = z if kind == "call" else -z
    return S * math.exp(-(x * sig * math.sqrt(T) - (r + 0.5 * sig**2) * T))


class Chain:
    def __init__(self, base_iv=0.60, skew=0.15):
        self.base_iv, self.skew = base_iv, skew

    def iv(self, dte, strike, spot):
        return max(self.base_iv - self.skew * math.log(strike / spot), 0.05)


def plan(direction, S, chain, delta=0.30, dte=30, width=None):
    kind = "put" if direction == "bull" else "call"
    T = dte / 365
    if width is None:
        width = max(round(S * 0.02, -1), 10.0)
    sig = max(chain.iv(dte, S, S), 0.01)
    for _ in range(2):
        K1 = strike_for_delta(kind, delta, S, T, sig)
        sig = max(chain.iv(dte, K1, S), 0.01)
    K2 = K1 - width if kind == "put" else K1 + width
    iv1, iv2 = max(chain.iv(dte, K1, S), .01), max(chain.iv(dte, K2, S), .01)
    credit = bs(kind, S, K1, T, iv1) - bs(kind, S, K2, T, iv2)
    return dict(K1=K1, K2=K2, width=width, credit=credit, ratio=credit / width,
                iv1=iv1, iv2=iv2, pop=1 - delta)


print("== bull put, defaults (iv .60, delta .30, 30dte, spot 2300)")
p = plan("bull", 2300.0, Chain())
print({k: round(v, 4) for k, v in p.items()})

print("== bear call, defaults")
p = plan("bear", 2300.0, Chain())
print({k: round(v, 4) for k, v in p.items()})

for name, kw in [("delta .02 dte 7", dict(delta=.02, dte=7)),
                 ("iv .30", None), ("iv .90", None)]:
    if kw:
        p = plan("bull", 2300.0, Chain(), **kw)
    elif name == "iv .30":
        p = plan("bull", 2300.0, Chain(base_iv=.30))
    else:
        p = plan("bull", 2300.0, Chain(base_iv=.90))
    print(f"{name:>16}: K1={p['K1']:.2f} ratio={p['ratio']:.3f} "
          f"{'PASS' if p['ratio'] >= .25 else 'REFUSED'}")

# delta recovery check
T = 30 / 365
sig = .6
K = strike_for_delta("put", .30, 2300.0, T, sig)
h = .01
fd = (bs("put", 2300 + h, K, T, sig) - bs("put", 2300 - h, K, T, sig)) / (2 * h)
print(f"delta recovery: strike={K:.2f} finite-diff delta={abs(fd):.5f} (want .30)")

