def _range_line(payload: dict[str, Any]) -> str:
    """Measured range, or a loud admission that it is not measured.

    A wide band and an unknown band must never look the same: one is confidence,
    the other is an absence of information.
    """
    ranges = payload.get("range") or {}
    status = ranges.get("status")
    if status not in {"ok", "mismatch"}:
        reason = ranges.get("reason", "not requested")
        return (
            "<div style='font-size:12px;margin-top:4px;color:#b35c00'>"
            f"range UNMEASURED · {html.escape(str(reason))}</div>"
        )

    measured = ranges.get("timeframes") or {}
    bits = [
        f"{timeframe} ATR {row['atr_pct']:.2f}%"
        for timeframe, row in measured.items()
        if row.get("atr_pct") is not None
    ]
    compression = ranges.get("compression") or {}
    if compression.get("percentile") is not None:
        bits.append(
            f"compression {compression['percentile']:.0f}th pctile ({compression['reads']})"
        )
    if status == "mismatch":
        bits.append("local EMAs DISAGREE with the feed")
    colour = "#b35c00" if status == "mismatch" else "#374151"
    return (
        f"<div style='font-size:12px;margin-top:4px;color:{colour}'>"
        + " · ".join(html.escape(bit) for bit in bits)
        + "</div>"
    )

